def brackets(n):
    valid=[]
    for p in itertools.product('()',repeat=2*n):
        bal=0
        for c in p:
            bal+=1 if c=='(' else -1
            if bal<0: break
        else:
            if bal==0: valid.append(''.join(p))
    return valid
