def queens(n):
    out=[]
    for p in itertools.permutations(range(n)):
        if len({i-p[i] for i in range(n)})==n and len({i+p[i] for i in range(n)})==n:
            out.append(['.'*c+'Q'+'.'*(n-c-1) for c in p])
    return out
